\label{thm:unboxed}
Let $m\ge 9$, and let $a\ne b$ be integers with $a,b\ge 7$. Then the power series
\[
E_{a,b,m}(q)=\frac{(1-q)^2}{(1-q^a)(1-q^b)\,(q;q)_m}
\]
has constant term $1$, coefficient $-1$ at $q^1$, and non-negative coefficients at $q^t$ for all $t\ge 2$.

\label{lem:defect}
Let $U(q)=\sum_{s}u_sq^s\in\mathbb{Z}[q]$ be reciprocal, let $b\ge 2$, and suppose that $P(q)=U(q)/[b]_q$ is a polynomial of degree $D\ge 3$. Assume that
\begin{enumerate}
\item[(i)] $u_0=1$ and $u_1=0$;
\item[(ii)] $u_{s}\ge u_{s-1}$ for $2\le s\le \lfloor D/2\rfloor$;
\item[(iii)] if $b+1\le \lfloor D/2\rfloor$, then $u_{b+1}>u_b$.
\end{enumerate}
Then $[q^1]P=[q^{D-1}]P=-1$, and all other coefficients of $P$ are non-negative.

\label{thm:reduction}
Let $m\ge 2$ with $m\not\equiv 2,3\pmod 5$, and let
\[
U_m(q)=\frac{1}{[2m-1]_q}\genfrac{[}{]}{0pt}{}{6m}{m}_q,\qquad V_m(q)=\frac{1}{[3m-1]_q}\genfrac{[}{]}{0pt}{}{6m}{m}_q.
\]
Suppose that one of the following holds:
\begin{enumerate}
\item[(H$_U$)] the coefficients $u_s$ of $U_m$ satisfy $u_s\ge u_{s-1}$ for $2\le s\le \lfloor D_m/2\rfloor$ and $u_{3m}>u_{3m-1}$;
\item[(H$_V$)] the coefficients $v_s$ of $V_m$ satisfy $v_s\ge v_{s-1}$ for $2\le s\le \lfloor D_m/2\rfloor$ and $v_{2m}>v_{2m-1}$.
\end{enumerate}
Then $[q^1]P^{(m)}=[q^{D_m-1}]P^{(m)}=-1$, and all other coefficients of $P^{(m)}$ are non-negative.

\label{thm:computation}
For every $m$ with $2\le m\le 300$ and $m\not\equiv 2,3\pmod 5$:
\begin{enumerate}
\item if $m\notin\{4,6\}$, then (H$_U$) holds; moreover $U_m$ is weakly increasing from $q^1$ up to its middle coefficient;
\item if $m\notin\{4,5,6\}$, then (H$_V$) also holds;
\item for $m\in\{4,6\}$, the polynomial $P^{(m)}$ has four negative coefficients (each equal to $-1$), namely at $q^1,q^5,q^{59},q^{63}$ for $m=4$ and at $q^1,q^7,q^{147},q^{153}$ for $m=6$.
\end{enumerate}
Consequently, Conjecture~\ref{conj:GK} holds for all $n\le 60$, and $P^{(m)}$ has exactly the two exceptional coefficients $-1$ for all $m\le 300$ with $m\not\equiv 2,3\pmod 5$ and $m\notin\{1,4,6\}$.

\label{lem:K}
Let $z=re^{i\varphi}$.
\begin{enumerate}
\item[(i)] $K(r)>0$ and $|K(z)|\le 4A^2K(r)$.
\item[(ii)] $\beta:=rK'(r)/K(r)$ satisfies $-\min(2s,5m)\le\beta\le0$.
\item[(iii)] Let $f(\varphi)=\log K(re^{i\varphi})$, continued along the arc from $\varphi=0$. Then $f'(0)=i\beta$, and $|f(\varphi)-f(0)-i\beta\varphi|\le\frac12H\varphi^2$, where $H=4s^2$ in general, and $H=4.76m^2$ if $\theta<\frac1{6m}$ and $|\varphi|\le\frac1{6m}$.
\end{enumerate}

\label{thm:orbit}
Let $m\ge 2$ with $m\not\equiv 2,3\pmod 5$, and define
\[
F^{(m)}(q)=\sum_{\substack{l+i+j=m\\ \gcd(i,a)=\gcd(j,b)=1}}q^{e(l,i,j)}\genfrac{[}{]}{0pt}{}{c}{l}_q\cdot\frac{1}{[a]_q}\genfrac{[}{]}{0pt}{}{a}{i}_q\cdot\frac{1}{[b]_q}\genfrac{[}{]}{0pt}{}{b}{j}_q,
\qquad E^{(m)}=P^{(m)}-F^{(m)}.
\]
Then:
\begin{enumerate}
\item $F^{(m)}(q)$ is a polynomial with non-negative integer coefficients, and $F^{(m)}(1)$ is the number of $\mathbb Z_a\times\mathbb Z_b$-orbits of $m$-combinations of $\Gamma_m$ of free type;
\item $E^{(m)}(q)$ is a polynomial, and
\[
[a]_q[b]_q\,E^{(m)}(q)=\sum_{\substack{l+i+j=m\\ \gcd(i,a)>1\text{ or }\gcd(j,b)>1}}q^{e(l,i,j)}\genfrac{[}{]}{0pt}{}{c}{l}_q\genfrac{[}{]}{0pt}{}{a}{i}_q\genfrac{[}{]}{0pt}{}{b}{j}_q;
\]
\item consequently, Conjecture~\ref{conj:general} for $m$ is implied by the statement that $E^{(m)}(q)+q+q^{D_m-1}$ has non-negative coefficients.
\end{enumerate}
